/// <summary>
/// Data contract class as a response for service <c>METPurchaseOrderService</c>
/// </summary>
[DataContractAttribute]
class METPurchaseOrderServiceResponseContract extends METBaseResponseContract
{
}

Method.Source:
    /// <summary>
    /// Contruct a new Response contract
    /// </summary>
    /// <param name = "_result">Result of the update</param>
    /// <param name = "message">Message Result</param>
    /// <returns>new contract</returns>
    public static METPurchaseOrderServiceResponseContract newFromParameters(METProcessingStatus _result, Description255 _message)
    {
        METPurchaseOrderServiceResponseContract purchaseOrderResponse = new METPurchaseOrderServiceResponseContract();

        purchaseOrderResponse.parmResult(enum2Symbol(enumNum(METProcessingStatus), enum2int(_result)));
        purchaseOrderResponse.parmMessage(_message);

        return purchaseOrderResponse;
    }
